mapper.select:
       SELECT TM.CAR_NO, TM.NUM_KIND, TM.USE_YN, NC.CARID_NO,
               TO_CHAR(TM.INPUT_DT, 'YYYY-MM-DD') as INPUT_DT, TO_CHAR(TM.USE_DT, 'MM-DD HH24:MI') as USE_DT, TM.SERVICE_ID, 
               TM.PROC_ST, TM.INS_USER, TM.INS_DATE, 
               TM.UPD_USER, TM.UPD_DATE, TM.GOVT_ID,
		        CD.DELIVERY_GB, CD.RECEIVE_NM, PKG_COMMON.FN_DECRYPT(CD.RECEIVE_TEL_NO) AS RECEIVE_TEL_NO, NC.IMSINUM_YN, TM.HOLE_YN, 
		        PKG_COMMON.FN_DECRYPT(CD.DELIVERY_ADDR) || ' ' || PKG_COMMON.FN_DECRYPT(CD.DELIVERY_ADDR_DT) as DELIVERY_ADDR, NVL2(CD.RECEIVE_TEL_NO, PKG_COMMON.FN_DECRYPT(CD.RECEIVE_TEL_NO) || ',', '') || PKG_COMMON.FN_DECRYPT(CD.STATUS_SMS_NO) as SMS_NO, CD.CUSTOMER_NM, NC.CAR_NM, PKG_COMMON.FN_DECRYPT(CD.STATUS_SMS_NO) AS STATUS_SMS_NO,
		       CD.INSTALL_NM, PKG_COMMON.FN_DECRYPT(CD.INSTALL_TEL_NO) AS INSTALL_TEL_NO, CD.INSTALL_DT, CD.INSTALL_TM,
		       (SELECT SERIAL_NO FROM (SELECT CP.SERVICE_ID, SERIAL_NO FROM TR_CAR_PAPER CP, TM_NUMPLATE_LIST TM WHERE CP.SERVICE_ID = TM.SERVICE_ID ORDER BY PRINT_DT DESC) CPP WHERE CPP.SERVICE_ID = TM.SERVICE_ID AND ROWNUM = 1) as SERIAL_NO,
		       TM.SPECIAL_YN, TM.ASSIGN_CD, TM.SEAL_YN, TO_CHAR(TM.MAKE_DT, 'YYYY-MM-DD') as MAKE_DT
        FROM TM_NUMPLATE_LIST TM
        LEFT OUTER JOIN TR_SERVICE TR
        ON TM.SERVICE_ID = TR.SERVICE_ID
    	LEFT OUTER JOIN
        TR_CARNO_DETACH CD
            ON TM.SERVICE_ID = CD.SERVICE_ID  
        LEFT OUTER JOIN
        TR_NEWCAR NC
            ON TM.SERVICE_ID = NC.SERVICE_ID
        WHERE 1=1

            AND TO_CHAR(TM.INPUT_DT, 'YYYYMMDD') BETWEEN #{START_DT} AND #{END_DT}


            AND TO_CHAR(TM.USE_DT, 'YYYYMMDD') BETWEEN #{START_DT} AND #{END_DT}


            AND TO_CHAR(TM.MAKE_DT, 'YYYYMMDD') BETWEEN #{START_DT} AND #{END_DT}


            AND TR.SERVICE_ID = #{SERVICE_ID}


            AND TR.GOVT_ID = #{GOVT_ID}




        		AND TM.CAR_NO LIKE DECODE(LENGTH(#{CAR_NO}), 7, SUBSTR(#{CAR_NO}, 1, 3), DECODE(LENGTH(#{CAR_NO}), 8, SUBSTR(#{CAR_NO}, 1, 4))) || '%' AND SUBSTR(TM.CAR_NO, -4) BETWEEN SUBSTR(#{CAR_NO}, -4) AND #{END_CAR_NO}


        		AND ((TM.CAR_NO LIKE '%' || #{CAR_NO} || '%') OR (NC.CARID_NO LIKE '%' || #{CAR_NO} || '%'))




            AND TM.USE_YN = #{USE_YN}


            AND TM.PROC_ST = #{PROC_ST}



	            AND TM.NUM_KIND = #{NUM_KIND}



            AND TR.WORK_CD = #{WORK_CD}


            AND TR.COMPANY_ID = #{COMPANY_ID}




                    AND CD.DELIVERY_GB NOT IN ('STARA', 'OBS')


                    AND CD.DELIVERY_GB IN 

                		#{gb}





        	AND (PKG_COMMON.FN_DECRYPT(CD.DELIVERY_ADDR) LIKE #{DELIVERY_ADDR} || '%' 

        		OR PKG_COMMON.FN_DECRYPT(CD.DELIVERY_ADDR) LIKE '서울%' OR PKG_COMMON.FN_DECRYPT(CD.DELIVERY_ADDR) LIKE '경기%' OR PKG_COMMON.FN_DECRYPT(CD.DELIVERY_ADDR) LIKE '인천%'   


        		OR (PKG_COMMON.FN_DECRYPT(CD.DELIVERY_ADDR) NOT LIKE '서울%' AND PKG_COMMON.FN_DECRYPT(CD.DELIVERY_ADDR) NOT LIKE '경기%' AND PKG_COMMON.FN_DECRYPT(CD.DELIVERY_ADDR) NOT LIKE '인천%')  


        		OR PKG_COMMON.FN_DECRYPT(CD.DELIVERY_ADDR) LIKE '충청북도%'


        		OR PKG_COMMON.FN_DECRYPT(CD.DELIVERY_ADDR) LIKE '충청남도%'


        		OR PKG_COMMON.FN_DECRYPT(CD.DELIVERY_ADDR) LIKE '경상북도%'


        		OR PKG_COMMON.FN_DECRYPT(CD.DELIVERY_ADDR) LIKE '경상남도%' 

        		)


            AND SUBSTR(TO_CHAR(TR.REQUEST_DT, 'HH24'), 1, 2) IN

                #{t}



            AND TM.HOLE_YN = #{HOLE_YN}


            AND TM.SEAL_YN = #{SEAL_YN}


            AND TM.SPECIAL_YN = #{SPECIAL_YN}




        			AND TM.ASSIGN_CD IS NULL




        					AND TM.ASSIGN_CD IN (SELECT COMPANY_ID || BRANCH_ID FROM TM_CARNO_COMPANY WHERE COMPANY_ID = 'BITS' AND SUBSTR(BRANCH_NM, 0,3) = '수도권' AND USE_YN = 'Y')


        					AND TM.ASSIGN_CD like #{ASSIGN_CD}

SELECT CP.SERVICE_ID, TS.CAR_NO, TS.COMPANY_ID, TC.COMPANY_NM, TO_CHAR(CP.PRINT_DT, 'YYYYMMDD') AS PRINT_DT FROM TR_CAR_PAPER CP, TR_SERVICE TS, TM_COMPANY TC WHERE CP.SERVICE_ID = TS.SERVICE_ID AND TS.COMPANY_ID = TC.COMPANY_ID
AND TS.COMPANY_ID = #{COMPANY_ID}
ORDER BY CP.PRINT_DT DESC

SELECT NL.NUM_ID, NL.CAR_NO, NL.COMPANY_ID, TC.COMPANY_NM, TO_CHAR(NL.ISSUE_DT, 'YYYYMMDD') AS ISSUE_DT, TO_CHAR(NL.RETURN_DT, 'YYYYMMDD') AS RETURN_DT FROM TM_NUMPLATE_LIST NL, TM_COMPANY TC WHERE NL.COMPANY_ID = TC.COMPANY_ID(+) AND NL.NUM_ST = 'TEMP'
AND NL.COMPANY_ID = #{COMPANY_ID}
ORDER BY NL.ISSUE_DT DESC

SELECT NS.SUPPLY_ID, NS.COMPANY_ID, TC.COMPANY_NM, NS.SUPPLY_QTY, TO_CHAR(NS.SUPPLY_DT, 'YYYYMMDD') AS SUPPLY_DT FROM TM_NUMPLATE_SUPPLY NS, TM_COMPANY TC WHERE NS.COMPANY_ID = TC.COMPANY_ID(+)
AND NS.COMPANY_ID = #{COMPANY_ID}
ORDER BY NS.SUPPLY_DT DESC

SELECT CAR_NO FROM ( SELECT CAR_NO FROM TM_NUMPLATE_LIST WHERE USE_YN = 'N' AND CAR_NO IN
#{carNo}
AND ( #{CONDITION} = 'NOT' OR ( LENGTH(#{CONDITION}) = 2 AND REGEXP_LIKE(#{CONDITION}, '^[0-9]{2}$') AND SUBSTR(CAR_NO, -1) = SUBSTR(#{CONDITION}, 2, 1) ) )
ORDER BY DBMS_RANDOM.VALUE ) WHERE ROWNUM <= #{LIMIT}

mapper.update:

UPDATE TM_NUMPLATE_LIST
   SET USE_YN = #{USE_YN}


    , SERVICE_ID = NULL
    , UPD_USER = #{LOGIN_ID}
    , USE_DT = NULL


    , SERVICE_ID = #{SERVICE_ID}
    , CARID_NO = #{CARID_NO}
    , UPD_USER = #{LOGIN_ID}
    , UPD_DATE = SYSDATE


 WHERE CAR_NO = #{CAR_NO}

UPDATE TR_CARNO_DETACH
   SET NUM_MEMO_TX = #{NUM_MEMO_TX},
       UPD_DATE = SYSDATE

     , INSTALL_DT = TO_DATE(#{INSTALL_DT}, 'YYYY-MM-DD')
     , INSTALL_TM = #{INSTALL_TM}

 WHERE SERVICE_ID = #{SERVICE_ID}
